void plot_pixel(int x, int y, short int color) {
  if (x < 0 || x >= SCREEN_W || y < 0 || y >= SCREEN_H) return;
  volatile short int* vga =
      (volatile short int*)(pixel_buffer_start + (y << 10) + (x << 1));
  *vga = color;
}

// Draw diemX by diemY block
void plot_block(int x, int y, short int color, int diemeX, int diemY) {
  for (int dx = 0; dx < diemeX; dx++) {
    for (int dy = 0; dy < diemY; dy++) {
      plot_pixel(dx + x, dy + y, color);
    }
  }
}

void clear_screen(void) {
  int x, y;
  for (y = 0; y < SCREEN_H; y++)
    for (x = 0; x < SCREEN_W; x++) plot_pixel(x, y, bg_grid[y][x]);
}

void draw_rect(int x1, int y1, int x2, int y2, short int color) {
  int x, y;
  for (y = y1; y <= y2; y++) {
    for (x = x1; x <= x2; x++) {
      if (color == BLACK){
        plot_pixel(x, y, bg_grid[y][x]);
      } else {
        plot_pixel(x,y,color);
      }
    }
  }
}

void draw_circle(int cx, int cy, int r, short int color) {
  int x, y;
  for (y = -r; y <= r; y++) {
    for (x = -r; x <= r; x++){
      if (x * x + y * y <= r * r){
        if (color == BLACK){
          plot_pixel(cx + x, cy + y, bg_grid[cy + y][cx + x]);
        } else {
          plot_pixel(cx + x, cy + y, color);
        }



        
      }
    }
  }
    
       
}

// color shading for beveled board
short int darken565(short int color, int amt) {
  int r = (color >> 11) & 0x1F;
  int g = (color >> 5) & 0x3F;
  int b = color & 0x1F;
  r = r > amt ? r - amt : 0;
  g = g > amt * 2 ? g - amt * 2 : 0;
  b = b > amt ? b - amt : 0;
  return (short int)((r << 11) | (g << 5) | b);
}

short int lighten565(short int color, int amt) {
  int r = (color >> 11) & 0x1F;
  int g = (color >> 5) & 0x3F;
  int b = color & 0x1F;
  r = r + amt < 32 ? r + amt : 31;
  g = g + amt * 2 < 64 ? g + amt * 2 : 63;
  b = b + amt < 32 ? b + amt : 31;
  return (short int)((r << 11) | (g << 5) | b);
}

void draw_char(int x, int y, char c, short int color) {
  int idx;
  // Contiguous hex ascii values for the symbols (space->/) in bitmap
  // Used LLM for conversions
  if (c >= 0x20 && c < 0x2F) idx = c - 0x20;
  // Start point 0 used to find all char indices, shifted by start of 0
  else if (c >= '0' && c <= '9')
    idx = (c - '0') + 16;
  // Start point A used to find all char indices, shifted by start of A
  else if (c >= 'A' && c <= 'Z')
    idx = (c - 'A') + 26;
  else if (c == ' ')
    idx = 0;
  else
    return;
  for (int row = 0; row < 7; row++) {
    unsigned char line = font5x7[idx][row];
    for (int col = 0; col < 5; col++)
      if (line & (0x10 >> col)) plot_pixel(x + col, y + row, color);
  }
}

void draw_char_scaled(int x, int y, char c, short int color, int scale) {
  int idx;
  // Contiguous hex ascii values for the symbols (space->/) in bitmap
  // Used LLM for conversions
  if (c >= 0x20 && c <= 0x2F) idx = c - 0x20;
  // Start point 0 used to find all char indices, shifted by start of 0
  else if (c >= '0' && c <= '9')
    idx = (c - '0') + 16;
  // Start point A used to find all char indices, shifted by start of A
  else if (c >= 'A' && c <= 'Z')
    idx = (c - 'A') + 26;
  else
    return;
  for (int row = 0; row < 7; row++) {
    unsigned char line = font5x7[idx][row];
    for (int col = 0; col < 5; col++)
      if (line & (0x10 >> col))
        plot_block(x + col * scale, y + row * scale, color, scale, scale);
  }
}

void draw_text_scaled(int x, int y, char* text, short int colour, int scale) {
  // Calculate text length
  int msgLengthInChar = 0;
  while (text[msgLengthInChar] != '\0') msgLengthInChar++;

  for (int currChar = 0; text[currChar] != '\0'; currChar++) {
    draw_char_scaled(x + currChar * (CHAR_WIDTH * scale), (int)y,
                     text[currChar], colour, scale);
  }
}

// Draw countdown timer to the right of the board
// Shows seconds left in the current player's color
void draw_timer(int seconds, short int color) {
  int tx = BOARD_X + COLS * (CELL_SIZE + CELL_GAP) + 8;
  int ty = BOARD_Y + (ROWS * (CELL_SIZE + CELL_GAP)) / 2 - 4;

  // Clear the timer area
  draw_rect(tx, ty, tx + 14, ty + 8,  BLACK);

  // Draw two-digit countdown (e.g. "10", " 5")
  int tens = seconds / 10;
  int ones = seconds % 10;
  if (tens > 0) draw_char(tx, ty, '0' + tens, color);
  draw_char(tx + 7, ty, '0' + ones, color);
}

void draw_cell(int r, int c) {
  int cx = BOARD_X + c * (CELL_SIZE + CELL_GAP) + CELL_SIZE / 2;
  int cy = BOARD_Y + r * (CELL_SIZE + CELL_GAP) + CELL_SIZE / 2;
  draw_circle(cx, cy, CIRCLE_R, BLACK);
  if (board[r][c] == PLAYER1)
    draw_circle(cx, cy, CIRCLE_R - 1, RED);
  else if (board[r][c] == PLAYER2)
    draw_circle(cx, cy, CIRCLE_R - 1, YELLOW);
}

void draw_cursor(
    int col, short int color) {  // added color param for player turn indicator
  draw_rect(BOARD_X - 2, BOARD_Y - 12,
            BOARD_X + COLS * (CELL_SIZE + CELL_GAP) + 1, BOARD_Y - 3, BLACK);
  int cx = BOARD_X + col * (CELL_SIZE + CELL_GAP) + CELL_SIZE / 2;
  int ay = BOARD_Y - 10;
  int i, w;
  for (i = 0; i < 6; i++) {
    w = 5 - i;
    draw_rect(cx - w, ay + i, cx + w, ay + i, color);
  }
}

void draw_board(int cursorColumn,
                short int cursorColor) {  // added cursorColor param
  int r, c;

  // beveled 3D board frame ---
  int bx1 = BOARD_X - 2;
  int by1 = BOARD_Y - 2;
  int bx2 = BOARD_X + COLS * (CELL_SIZE + CELL_GAP) + 1;
  int by2 = BOARD_Y + ROWS * (CELL_SIZE + CELL_GAP) + 1;
  short int board_mid = 0x2196;  // richer medium blue
  short int board_light = lighten565(board_mid, 7);
  short int board_dark = darken565(board_mid, 6);

  draw_rect(bx1, by1, bx2, by2, board_mid);
  draw_rect(bx1, by1, bx2, by1 + 1, board_light);
  draw_rect(bx1, by1, bx1 + 1, by2, board_light);
  draw_rect(bx1, by2 - 1, bx2, by2, board_dark);
  draw_rect(bx2 - 1, by1, bx2, by2, board_dark);
  //

  for (r = 0; r < ROWS; r++)
    for (c = 0; c < COLS; c++) draw_cell(r, c);

  int num_y = BOARD_Y + ROWS * (CELL_SIZE + CELL_GAP) + 4;
  for (c = 0; c < COLS; c++) {
    int nx = BOARD_X + c * (CELL_SIZE + CELL_GAP) + CELL_SIZE / 2 - 2;
    draw_char(nx, num_y, '1' + c, WHITE);
  }

  draw_cursor(cursorColumn, cursorColor);
}

// drop animation

void delay_loop(int count) {
  volatile int d;
  for (d = 0; d < count; d++);
}

int cell_center_y(int row) {
  return BOARD_Y + row * (CELL_SIZE + CELL_GAP) + CELL_SIZE / 2;
}

int cell_center_x(int col) {
  return BOARD_X + col * (CELL_SIZE + CELL_GAP) + CELL_SIZE / 2;
}

// Draw a colored piece only within the black hole of a specific cell
void draw_piece_in_hole(int hole_row, int col, int piece_cy, int piece_r,
                        short int color) {
  // hole center
  int hcx = cell_center_x(col);
  int hcy = cell_center_y(hole_row);
  int hr = CIRCLE_R;
  int px, py;
  for (py = -hr; py <= hr; py++) {
    for (px = -hr; px <= hr; px++) {
      int sx = hcx + px;
      int sy = hcy + py;
      // inside circle check
      if (px * px + py * py > hr * hr) continue;
      int dx = sx - hcx;
      int dy = sy - piece_cy;
      // if pixel is also inside the falling pieces circle
      if (dx * dx + dy * dy > piece_r * piece_r) continue;
      plot_pixel(sx, sy, color);
    }
  }
}

// Clear a hole by redrawing it black, then redrawing any existing piece
// Uses existing draw_cell logic inline to avoid double-drawing
void clear_hole(int row, int col) {
  int hcx = cell_center_x(col);
  int hcy = cell_center_y(row);
  draw_circle(hcx, hcy, CIRCLE_R, BLACK);
  if (board[row][col] == PLAYER1)
    draw_circle(hcx, hcy, CIRCLE_R - 1, RED);
  else if (board[row][col] == PLAYER2)
    draw_circle(hcx, hcy, CIRCLE_R - 1, YELLOW);
}

// Draw animated piece through all overlapping holes in this column
void draw_anim(int col, int piece_cy, int piece_r, short int color) {
  int r;
  // loop through all rows
  for (r = 0; r < ROWS; r++) {
    int hcy = cell_center_y(r);
    int dist = piece_cy - hcy;
    if (dist < 0) dist = -dist;
    // if distance between piece center and hole center is less than piece rad
    // to circle rad
    if (dist < piece_r + CIRCLE_R) {
      draw_piece_in_hole(r, col, piece_cy, piece_r, color);
    }
  }
}

// Erase only holes that old position touched but new position does not
void erase_anim_selective(int col, int old_cy, int new_cy, int piece_r) {
  int r;
  for (r = 0; r < ROWS; r++) {
    int hcy = cell_center_y(r);  // center of row r
    int old_dist =
        old_cy - hcy;  // vert dist between old cy and this holes center
    if (old_dist < 0) old_dist = -old_dist;
    int old_touched =
        (old_dist < piece_r + CIRCLE_R);  // circles overlapped if dist between
                                          // centers is less than sum of radii
    int new_dist =
        new_cy - hcy;  // vert dist between new cy and this holes center
    if (new_dist < 0) new_dist = -new_dist;
    int new_touched = (new_dist < piece_r + CIRCLE_R);
    if (old_touched && !new_touched) {
      clear_hole(r, col);  // if not overlapping anymore clear
    }
  }
}

// Erase all holes touched by the piece at this position
void erase_anim_all(int col, int piece_cy, int piece_r) {
  int r;
  for (r = 0; r < ROWS; r++) {
    int hcy = cell_center_y(r);
    int dist = piece_cy - hcy;
    if (dist < 0) dist = -dist;
    if (dist < piece_r + CIRCLE_R) {
      clear_hole(r, col);
    }
  }
}

// Forward declaration for get_open_row (defined in LOGIC section)
int get_open_row(int col);

// Animate a piece falling into the given column, then commit to board
void drop_piece_animated(int col, int piece) {
  int target_row = get_open_row(col);
  if (target_row < 0) return;

  short int color = (piece == PLAYER1) ? RED : YELLOW;
  int target_y = cell_center_y(target_row);  // where piece will end
  int start_y = cell_center_y(0);            // where piece will start, top row
  int piece_r = CIRCLE_R - 1;

  // Gravity fall
  int y = start_y;
  int prev_y = start_y;
  int velocity = 0;
  int first = 1;  // first frame flag

  while (y < target_y) {
    if (!first) {  // on frames not first, call erase to clean up where piece
                   // was
      draw_anim(col, y, piece_r, color);
      erase_anim_selective(col, prev_y, y, piece_r);
    } else {
      draw_anim(col, y, piece_r, color);
    }
    delay_loop(45000);  // control animation speed

    first = 0;  // no longer first flag
    prev_y = y;
    velocity += 2;
    y += velocity;
    if (y > target_y) y = target_y;  // prevent from overshooting target
  }

  // Snap to final position and clean up
  draw_anim(col, target_y, piece_r, color);
  erase_anim_selective(col, prev_y, target_y, piece_r);
  delay_loop(30000);  // brief pause before bounce begins

  // Phase 2: Bounce animation
  // Piece bounces 3 times with decreasing height for a natural landing feel
  // bounce_height starts at ~1 cell height and shrinks each iteration
  // Scale by row: bottom row gets full bounce, top row gets none
  // Offset keeps middle rows bouncing noticeably while top row stays at 0
  int bounce_height = target_row == 0
                          ? 0
                          : (CELL_SIZE + CELL_GAP) * (target_row + 2) / (ROWS + 1);
  int b;
  for (b = 0; b < 3 && bounce_height >= 4; b++) {
    int prev_offset = 0;

    // piece moves upward from target position
    int offset;
    for (offset = 2; offset <= bounce_height; offset += 2) {
      int new_y = target_y - offset;
      int old_y = target_y - prev_offset;
      draw_anim(col, new_y, piece_r, color);
      erase_anim_selective(col, old_y, new_y, piece_r);
      delay_loop(36000);
      prev_offset = offset;
    }

    // Fall back down - piece drops back to target position
    for (offset = bounce_height - 2; offset >= 0; offset -= 2) {
      int new_y = target_y - offset;
      int old_y = target_y - prev_offset;
      draw_anim(col, new_y, piece_r, color);
      erase_anim_selective(col, old_y, new_y, piece_r);
      delay_loop(36000);
      prev_offset = offset;
    }

    // Ensure piece ends exactly at target_y after each bounce
    draw_anim(col, target_y, piece_r, color);
    erase_anim_selective(col, target_y - prev_offset, target_y, piece_r);

    // Each bounce is ~40% the height of the previous one
    bounce_height = bounce_height * 2 / 5;  // ~30 -> 12 -> 4
  }

  // Final cleanup of all holes pieces touched
  erase_anim_all(col, target_y, piece_r);

  // Commit piece to board and draw final piece using existing draw_cell
  board[target_row][col] = piece;
  draw_cell(target_row, col);
}

//--------------------------------------------------LOGIC.C-------------------------------------------------------//

int inBoundRow(int row);
int inBoundCol(int col);

// Returns if the column can have a piece there
int is_valid_col(int col) {
  return col >= 0 && col < COLS && board[0][col] == EMPTY;
}

// Gets the first open row in a column
//-1 of no open row
int get_open_row(int col) {
  int r;
  for (r = ROWS - 1; r >= 0; r--)
    if (board[r][col] == EMPTY) return r;
  return -1;
}

// Places a piece in board array
// NOTE: implement a safeguard in gameloop
// Dont let input even occur if not valid
// Make sound or display somewhere its not valid
// Return row where placed
int place_piece(int col, int colour) {
  if (is_valid_col(col)) {
    int row = get_open_row(col);
    board[row][col] = colour;
    draw_cell(row, col);  // draws colour based on board colour
    return row;
  }
  return -1;  // wont ever reach this but for safety
}

int winDetected(int rowInput, int colInput, int colour) {
  // go 4 in all directions from piece and check if theres any 4 in a rows
  // Make sure that no moves exceed board bounds - if statement lock
  // Keep running tally in that direction

  int currRow = rowInput;
  int currCol = colInput;
  int counter;

  for (int dr = -1; dr <= 1; dr++) {
    for (int dc = -1; dc <= 1; dc++) {
      // Skip duplicate directions accounted for by 2 while loops
      if (!dr && !dc) continue;
      if (dr == 1) continue;

      counter = 1;

      // Walk positive direction
      currRow = rowInput + dr;
      currCol = colInput + dc;
      while (inBoundRow(currRow) && inBoundCol(currCol) &&
             (board[currRow][currCol] == colour)) {
        currRow += dr;
        currCol += dc;
        counter++;
      }

      // Walk negative direction
      currRow = rowInput - dr;
      currCol = colInput - dc;
      while (inBoundRow(currRow) && inBoundCol(currCol) &&
             (board[currRow][currCol] == colour)) {
        currRow -= dr;
        currCol -= dc;
        counter++;
      }

      if (counter >= 4) return 1;
    }
  }

  return 0;
}

int inBoundRow(int row) { return ((row >= 0) && (row < ROWS)); }

int inBoundCol(int col) { return ((col >= 0) && (col < COLS)); }

// less resource internsive
#define DRAW_DETECTED(fullBoard, win) fullBoard && !win

int boardFull() {
  // Only need to check top row
  for (int c = 0; c < COLS; c++) {
    if (board[0][c] == 0) {
      return 0;
    }
  }

  return 1;
}

void resetBoard() {
  for (int r = 0; r < ROWS; r++) {
    for (int c = 0; c < COLS; c++) {
      board[r][c] = 0;
    }
  }
}

//--------------------------------------------------AI.C-------------------------------------------------------//

// How many moves ahead the AI looks - kept small for speed on hardware
#define AI_DEPTH 4

// Score a single 4-cell window from the AI's (PLAYER2) perspective
// Awards points for AI piece groupings and penalizes opponent threats
int eval_window(int a, int b, int c, int d) {
  int win[4] = {a, b, c, d};
  int ai_count = 0, opp_count = 0, empty = 0;
  for (int i = 0; i < 4; i++) {
    if (win[i] == PLAYER2)
      ai_count++;
    else if (win[i] == PLAYER1)
      opp_count++;
    else
      empty++;
  }
  if (ai_count == 4) return 10000;               // AI win
  if (ai_count == 3 && empty == 1) return 50;    // 3 in a row with space
  if (ai_count == 2 && empty == 2) return 5;     // 2 in a row with space
  if (opp_count == 3 && empty == 1) return -80;  // block opponent threat
  return 0;
}

// Sum window scores in all four directions across the whole board
// Used as the heuristic when minimax hits its depth limit
int score_board() {
  int score = 0;
  // Horizontal windows
  for (int r = 0; r < ROWS; r++)
    for (int c = 0; c <= COLS - 4; c++)
      score += eval_window(board[r][c], board[r][c + 1], board[r][c + 2],
                           board[r][c + 3]);
  // Vertical windows
  for (int c = 0; c < COLS; c++)
    for (int r = 0; r <= ROWS - 4; r++)
      score += eval_window(board[r][c], board[r + 1][c], board[r + 2][c],
                           board[r + 3][c]);
  // Diagonal windows (down-right)
  for (int r = 0; r <= ROWS - 4; r++)
    for (int c = 0; c <= COLS - 4; c++)
      score += eval_window(board[r][c], board[r + 1][c + 1],
                           board[r + 2][c + 2], board[r + 3][c + 3]);
  // Diagonal windows (up-right)
  for (int r = 3; r < ROWS; r++)
    for (int c = 0; c <= COLS - 4; c++)
      score += eval_window(board[r][c], board[r - 1][c + 1],
                           board[r - 2][c + 2], board[r - 3][c + 3]);
  return score;
}

// Minimax search with alpha-beta pruning
// maximizing=1 -> AI's turn (PLAYER2), 0 -> opponent's turn (PLAYER1)
// alpha/beta bounds let us skip branches that cannot improve the result
int minimax(int depth, int alpha, int beta, int maximizing) {
  if (depth == 0 || boardFull()) return score_board();

  if (maximizing) {
    int best = -1000000;
    for (int col = 0; col < COLS; col++) {
      if (!is_valid_col(col)) continue;
      int row = get_open_row(col);
      board[row][col] = PLAYER2;  // simulate AI move
      int val = winDetected(row, col, PLAYER2)
                    ? 100000 + depth
                    : minimax(depth - 1, alpha, beta, 0);
      board[row][col] = EMPTY;  // undo move
      if (val > best) best = val;
      if (best > alpha) alpha = best;
      if (alpha >= beta) break;  // prune remaining branches
    }
    return best;
  } else {
    int best = 1000000;
    for (int col = 0; col < COLS; col++) {
      if (!is_valid_col(col)) continue;
      int row = get_open_row(col);
      board[row][col] = PLAYER1;  // simulate opponent move
      int val = winDetected(row, col, PLAYER1)
                    ? -100000 - depth
                    : minimax(depth - 1, alpha, beta, 1);
      board[row][col] = EMPTY;  // undo move
      if (val < best) best = val;
      if (best < beta) beta = best;
      if (alpha >= beta) break;  // prune remaining branches
    }
    return best;
  }
}

// Picks the best column for the AI by trying every legal move and
// running minimax on the resulting position - returns chosen column
int get_ai_move() {
  int best_col = COLS / 2;  // default to center
  int best_score = -1000000;
  for (int col = 0; col < COLS; col++) {
    if (!is_valid_col(col)) continue;
    int row = get_open_row(col);
    board[row][col] = PLAYER2;
    int val = minimax(AI_DEPTH - 1, -1000000, 1000000, 0);
    board[row][col] = EMPTY;
    if (val > best_score) {
      best_score = val;
      best_col = col;
    }
  }
  return best_col;
}

//--------------------------------------------------SPLASH_SCREEN.C-------------------------------------------------------//
#define LS_BGCOLOR_FUNCTION(y) (((y) * 20 / SCREEN_H) + 7)

void drawImageArrayBG(const short int image[SCREEN_H][SCREEN_W]) {
    for (int y = 0; y < SCREEN_H; y++)
        for (int x = 0; x < SCREEN_W; x++)
            plot_pixel(x, y, image[y][x]);
}

void drawBlueGradientBG() {
  for (int y = 0; y < SCREEN_H; y++) {
    for (int x = 0; x < SCREEN_W; x++) {
      // Select subset of blue bits, only 7 to 28
      // Cleanly map inbetween colours to scale with y
      short int currBlue = LS_BGCOLOR_FUNCTION(y);
      plot_pixel(x, y, currBlue);
    }
  }
}

void drawGreenGradientBG() {
  for (int y = 0; y < SCREEN_H; y++) {
    for (int x = 0; x < SCREEN_W; x++) {
      // green is 32 to 2016
      // Cleanly map inbetween colours to scale with y
      short int green = (20 + ((y * 20 / SCREEN_H))) << 5;
      plot_pixel(x, y, green);
    }
  }
}

void drawRedGradientBG() {
  for (int y = 0; y < SCREEN_H; y++) {
    for (int x = 0; x < SCREEN_W; x++) {
      // Cleanly map inbetween colours to scale with y
      short int red = (0 + ((y * 31 / SCREEN_H))) << 11;
      plot_pixel(x, y, red);
    }
  }
}

void drawSelectArrow(int x, int y, short int colour, int length) {
  for (int curLen = 0; curLen <= length; curLen++) {
    plot_pixel(x - curLen, y + curLen, colour);
    plot_pixel(x - curLen, y - curLen, colour);

    // Fill empty space
    for (int currFillPoint = y + curLen; currFillPoint > y - curLen;
         currFillPoint--) {
      plot_pixel(x - curLen, currFillPoint, colour);
    }
  }
}

void eraseSelectArrow(int x, int y, int length) {
  for (int curLen = 0; curLen <= length; curLen++) {
    plot_pixel(x - curLen, y + curLen, LS_BGCOLOR_FUNCTION(y + curLen));
    plot_pixel(x - curLen, y - curLen, LS_BGCOLOR_FUNCTION(y - curLen));

    // Fill empty space
    for (int currFillPoint = y + curLen; currFillPoint > y - curLen;
         currFillPoint--) {
      plot_pixel(x - curLen, currFillPoint, LS_BGCOLOR_FUNCTION(currFillPoint));
    }
  }
}

int titleScreen() {
  // Acquire keyboard input
  kbInputKey kbUserInput;
  static kbInputKey prevInput = NONE;

  clear_screen();
  //drawImageArrayBG(bg_synthwave);
  drawBlueGradientBG();

  int titleXPos = 79;
  int titleYPos = 83;

  // shadow - slight shift and under title
  draw_text_scaled(titleXPos + 2, titleYPos + 2, "CONNECT 4", DARK_YELLOW, 3);
  draw_text_scaled(titleXPos, titleYPos, "CONNECT 4", YELLOW, 3);

  int playerTitleXPos = 140;
  int playerTitleYPos = 119;

  int AITitleXPos = playerTitleXPos;
  int AITitleYPos = 139;

  // plot_block(playerTitleXPos - 5, playerTitleYPos - 4, 0x03BF, 45, 15);
  // plot_block(AITitleXPos - 5, AITitleYPos - 4, 0x03BF, 45, 15);

  int noteDur = 200;
  playMusicalNote(261, noteDur);
  playMusicalNote(392, noteDur);
  playMusicalNote(440, noteDur);
  playMusicalNote(349, noteDur);
  playMusicalNote(523, noteDur);
  playMusicalNote(587, noteDur);


  draw_text_scaled(playerTitleXPos + 1, playerTitleYPos + 1, "PLAYER",
                   DARK_YELLOW, 1);
  draw_text_scaled(playerTitleXPos, playerTitleYPos, "PLAYER", WHITE, 1);

  draw_text_scaled((AITitleXPos + 12) + 1, AITitleYPos + 1, "AI", DARK_YELLOW,
                   1);
  draw_text_scaled((AITitleXPos + 12), AITitleYPos, "AI", WHITE, 1);

  // Draw initial cursor
  // Start on top button;
  int cursorXPos = 133;
  int cursorAIYPos = AITitleYPos + 3;
  int cursorPlayerYPos = playerTitleYPos + 3;

  int currModeSel = cursorPlayerYPos;
  drawSelectArrow(cursorXPos, currModeSel, YELLOW, 4);

  // Poll for enter key to go to game
  while (1) {
    kbUserInput = currInput;

    if (kbUserInput == UP && prevInput != UP && currModeSel == cursorAIYPos) {
      eraseSelectArrow(cursorXPos, currModeSel, 4);
      currModeSel = cursorPlayerYPos;
      drawSelectArrow(cursorXPos, currModeSel, YELLOW, 4);
      playMusicalNote(880, 30);
    }

    if (kbUserInput == DOWN && prevInput != DOWN &&
        currModeSel == cursorPlayerYPos) {
      eraseSelectArrow(cursorXPos, currModeSel, 4);
      currModeSel = cursorAIYPos;
      drawSelectArrow(cursorXPos, currModeSel, YELLOW, 4);
      playMusicalNote(880, 30);
    }

    if (kbUserInput == ENTER && prevInput != ENTER) {
      currInput = NONE;
      if (currModeSel == cursorPlayerYPos) return 0;
      return 1;
    }

    prevInput = kbUserInput;
  }
}


// one will have to be past
void endScreen(int endCause, int playerWinnerCol) {
  int textYPos = 97;
  isGameActive = 0;

  // draw
  if (endCause == 0) {
    drawBlueGradientBG();
    draw_text_scaled(109 + 2, textYPos + 2, "DRAW", DARK_YELLOW, 4);
    draw_text_scaled(109, textYPos, "DRAW", YELLOW, 4);

    playMusicalNote(400, 200);
    playMusicalNote(300, 200);
    playMusicalNote(200, 200);
  }

  // player win
  if (endCause == 1) {
    drawImageArrayBG(bg_synthwave);
    if (playerWinnerCol == YELLOW) {
      draw_text_scaled(70 + 3, textYPos -25 + 3, "YELLOW", BLACK, 5);
      draw_text_scaled(70, textYPos - 25, "YELLOW", CYAN, 5);

      draw_text_scaled(95 + 3, textYPos + 43 + 3 -25, "WINS!", BLACK, 5);
      draw_text_scaled(95, textYPos + 43 -25, "WINS!", CYAN, 5);

    } else if (playerWinnerCol == RED) {
      draw_text_scaled(36 + 2, textYPos + 2, "RED WINS!", BLACK, 5);
      draw_text_scaled(36, textYPos, "RED WINS!", CYAN, 5);
    }
    playMusicalNote(523, 150);
    playMusicalNote(659, 150);
    playMusicalNote(784, 150);
  }

  // player loss
  if (endCause == 2) {
    drawRedGradientBG();
    draw_text_scaled(45 + 2, textYPos + 2, "YOU LOSE", DARK_YELLOW, 5);
    draw_text_scaled(45, textYPos, "YOU LOSE", YELLOW, 5);

    playMusicalNote(523, 300);
    playMusicalNote(370, 300);
    playMusicalNote(311, 300);
  }

  draw_text_scaled(98, 220, "PRESS ENTER TO RESTART", WHITE, 1);
}



//--------------------------------------------------MAIN.C-------------------------------------------------------//

int playerWinner = -1;

short int runGame(int currentGameMode) {
  isGameActive = 1;
  // Acquire keyboard input
  kbInputKey kbUserInput, prevInput;
  prevInput = NONE;

  int currentPlayer = PLAYER1;
  int currentColumn = CURSOR_START_COL;
  int lastDrawnSeconds = -1;  // tracks last displayed value to avoid flicker

  clear_screen();

  drawImageArrayBG(bg_grid);
  draw_board(currentColumn, RED);
  reset_timer();

  //Game start jingle
  playMusicalNote(784, 100);
  playMusicalNote(659, 100);
  playMusicalNote(523, 100);
  playMusicalNote(784, 100);

  while (1) {
    // AI mode: PLAYER2 is the AI, make its move automatically
    if (currentGameMode == 1 && currentPlayer == PLAYER2) {
      int aiCol = get_ai_move();
      drop_piece_animated(aiCol, PLAYER2);
      int aiRow;
      for (aiRow = 0; aiRow < ROWS; aiRow++) {
        if (board[aiRow][aiCol] != EMPTY) break;
      }
      int winState = winDetected(aiRow, aiCol, PLAYER2);
      if (winState) {
        playerWinner = YELLOW;
        return 1;
      }
      if (DRAW_DETECTED(boardFull(), winState)) return 0;
      currentPlayer = PLAYER1;
      draw_cursor(currentColumn, RED);
      reset_timer();
      lastDrawnSeconds = -1;
      continue;
    }

    __asm__ volatile("csrc mstatus, %0" ::"r"(0b1000));  // disable interrupts
    kbUserInput = currInput;
    currInput = NONE;
    int sec = timer_seconds;
    int expired = timer_expired;
    __asm__ volatile("csrs mstatus, %0" ::"r"(0b1000));  // re-enable interrupts

    short int cursorColor = (currentPlayer == PLAYER1) ? RED : YELLOW;

    // Only redraw timer when the value changes
    if (sec != lastDrawnSeconds) {
      draw_timer(sec, cursorColor);
      lastDrawnSeconds = sec;
    }

    // Timer ran out - skip this players turn
    if (expired) {
      currentPlayer = (currentPlayer == PLAYER1) ? PLAYER2 : PLAYER1;
      cursorColor = (currentPlayer == PLAYER1) ? RED : YELLOW;
      draw_cursor(currentColumn, cursorColor);
      reset_timer();
      playMusicalNote(200, 400);
      lastDrawnSeconds = -1;  // so new 10 gets drawn immediately
      prevInput = kbUserInput;
      continue;
    }

    if (kbUserInput == LEFT && prevInput != LEFT && currentColumn > 0) {
      currentColumn--;
      draw_cursor(currentColumn, cursorColor);
      playMusicalNote(880, 30);
    }
    if (kbUserInput == RIGHT && prevInput != RIGHT && currentColumn < COLS - 1) {
      currentColumn++;
      draw_cursor(currentColumn, cursorColor);
      playMusicalNote(880, 30);
    }

    if (kbUserInput == ENTER && prevInput != ENTER) {
      if (is_valid_col(currentColumn)){
        drop_piece_animated(currentColumn, currentPlayer);
        playMusicalNote(250, 120);

        // Find the row where the piece landed (topmost non-empty in this column)
        int currRow;
        for (currRow = 0; currRow < ROWS; currRow++) {
          if (board[currRow][currentColumn] != EMPTY) break;
        }

        int winState = winDetected(currRow, currentColumn, currentPlayer);
        int drawState = DRAW_DETECTED(boardFull(), winState);

        if (winState) {
          playerWinner = (currentPlayer == PLAYER1) ? RED : YELLOW;
          isGameActive = 0;
          return 1;
        }

        if (drawState) {
          isGameActive = 0;
          return 0;
        }
        // Swap player and reset turn timer
        currentPlayer = (currentPlayer == PLAYER1) ? PLAYER2 : PLAYER1;
        cursorColor = (currentPlayer == PLAYER1) ? RED : YELLOW;
        draw_cursor(currentColumn, cursorColor);
        playMusicalNote(880, 30);
        reset_timer();
        lastDrawnSeconds = -1;
      }
      else { //Noise to reject placement
        playMusicalNote(150, 200);
      }
    }

    prevInput = kbUserInput;
  }
}


	
int main() {
  volatile int* pixel_ctrl_ptr = (int*)VGA_CTRL_PTR;
  pixel_buffer_start = *pixel_ctrl_ptr;
  PS2_SETUP();
  TIMER_SETUP();
  enable_interrupts();

  // 0 means player mode
  // 1 means AI mode
  while (1) {
    int currentGameMode = titleScreen();
    int endCause = runGame(currentGameMode);
    endScreen(endCause, playerWinner);

    currInput = NONE;
    while (currInput != ENTER);
    resetBoard();
    currInput = NONE;
    resetBoard();
    continue;
  }
  // Hold game at end and restart
  // Temporary loop structure
}